seo.schema:
Tu es un expert en Schema.org et données structurées.

Crée le code JSON-LD Schema.org complet pour:
Type de page: {pageType}
Nom: {brandName}
Thème: {theme}
Type de business: {businessType}

GÉNÈRE LE CODE JSON-LD COMPLET:

[Selon le type de page, générer le schema approprié]

SI PAGE = HOMEPAGE:
```json
{
  "@context": "https://schema.org",
  "@type": "Organization",
  "name": "{brandName}",
  "alternateName": "{nom alternatif si applicable}",
  "url": "https://www.example.com",
  "logo": "https://www.example.com/logo.png",
  "description": "{description complète 200 mots}",
  "email": "contact@example.com",
  "telephone": "+33-X-XX-XX-XX-XX",
  "address": {
    "@type": "PostalAddress",
    "streetAddress": "{Adresse}",
    "addressLocality": "{Ville}",
    "postalCode": "{Code postal}",
    "addressCountry": "FR"
  },
  "sameAs": [
    "https://www.facebook.com/page",
    "https://www.linkedin.com/company/page",
    "https://twitter.com/handle",
    "https://www.instagram.com/handle"
  ],
  "founder": {
    "@type": "Person",
    "name": "{Nom du fondateur}",
    "jobTitle": "CEO"
  },
  "foundingDate": "{YYYY}",
  "numberOfEmployees": {
    "@type": "QuantitativeValue",
    "value": {XX}
  },
  "aggregateRating": {
    "@type": "AggregateRating",
    "ratingValue": "4.9",
    "reviewCount": "XXX"
  },
  "contactPoint": {
    "@type": "ContactPoint",
    "telephone": "+33-X-XX-XX-XX-XX",
    "contactType": "customer service",
    "areaServed": "FR",
    "availableLanguage": ["French", "English"]
  }
}
```

SI PAGE = ARTICLE:
```json
{
  "@context": "https://schema.org",
  "@type": "Article",
  "headline": "{Titre de l'article}",
  "image": [
    "https://example.com/image.jpg"
  ],
  "datePublished": "{YYYY-MM-DD}",
  "dateModified": "{YYYY-MM-DD}",
  "author": {
    "@type": "Person",
    "name": "{Nom auteur}",
    "url": "https://example.com/author/nom"
  },
  "publisher": {
    "@type": "Organization",
    "name": "{brandName}",
    "logo": {
      "@type": "ImageObject",
      "url": "https://example.com/logo.png"
    }
  },
  "description": "{Meta description}",
  "articleBody": "{Extrait du contenu}",
  "mainEntityOfPage": {
    "@type": "WebPage",
    "@id": "https://example.com/article-url"
  },
  "keywords": "{keyword1, keyword2, keyword3}"
}
```

SI PAGE = SERVICE:
```json
{
  "@context": "https://schema.org",
  "@type": "Service",
  "serviceType": "{Type de service}",
  "provider": {
    "@type": "Organization",
    "name": "{brandName}"
  },
  "areaServed": {
    "@type": "Country",
    "name": "France"
  },
  "hasOfferCatalog": {
    "@type": "OfferCatalog",
    "name": "Nos services",
    "itemListElement": [
      {
        "@type": "OfferCatalog",
        "name": "{Nom service 1}",
        "itemListElement": [
          {
            "@type": "Offer",
            "itemOffered": {
              "@type": "Service",
              "name": "{Service détaillé 1}"
            }
          }
        ]
      }
    ]
  },
  "aggregateRating": {
    "@type": "AggregateRating",
    "ratingValue": "4.9",
    "reviewCount": "XXX"
  }
}
```

SI PAGE = PRODUIT:
```json
{
  "@context": "https://schema.org",
  "@type": "Product",
  "name": "{Nom du produit}",
  "image": [
    "https://example.com/product.jpg"
  ],
  "description": "{Description du produit}",
  "sku": "{SKU}",
  "brand": {
    "@type": "Brand",
    "name": "{brandName}"
  },
  "offers": {
    "@type": "Offer",
    "url": "https://example.com/product",
    "priceCurrency": "EUR",
    "price": "XXX.XX",
    "priceValidUntil": "{YYYY-MM-DD}",
    "availability": "https://schema.org/InStock",
    "seller": {
      "@type": "Organization",
      "name": "{brandName}"
    }
  },
  "aggregateRating": {
    "@type": "AggregateRating",
    "ratingValue": "4.8",
    "reviewCount": "XX"
  }
}
```

SI PAGE = FAQ:
```json
{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "{Question 1}",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "{Réponse complète 1}"
      }
    },
    {
      "@type": "Question",
      "name": "{Question 2}",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "{Réponse complète 2}"
      }
    }
  ]
}
```

SI PAGE = CONTACT + LOCAL BUSINESS:
```json
{
  "@context": "https://schema.org",
  "@type": "LocalBusiness",
  "name": "{brandName}",
  "image": "https://example.com/image.jpg",
  "@id": "https://example.com",
  "url": "https://example.com",
  "telephone": "+33-X-XX-XX-XX-XX",
  "priceRange": "€€-€€€",
  "address": {
    "@type": "PostalAddress",
    "streetAddress": "{Adresse}",
    "addressLocality": "{Ville}",
    "postalCode": "{CP}",
    "addressCountry": "FR"
  },
  "geo": {
    "@type": "GeoCoordinates",
    "latitude": XX.XXXXX,
    "longitude": X.XXXXX
  },
  "openingHoursSpecification": [
    {
      "@type": "OpeningHoursSpecification",
      "dayOfWeek": [
        "Monday",
        "Tuesday",
        "Wednesday",
        "Thursday",
        "Friday"
      ],
      "opens": "09:00",
      "closes": "18:00"
    }
  ],
  "sameAs": [
    "https://www.facebook.com/page",
    "https://www.linkedin.com/company/page"
  ]
}
```

SI PAGE = BREADCRUMB:
```json
{
  "@context": "https://schema.org",
  "@type": "BreadcrumbList",
  "itemListElement": [
    {
      "@type": "ListItem",
      "position": 1,
      "name": "Accueil",
      "item": "https://example.com"
    },
    {
      "@type": "ListItem",
      "position": 2,
      "name": "{Nom de page}",
      "item": "https://example.com/page"
    }
  ]
}
```

EXIGENCES:
- Code JSON-LD valide
- Toutes les propriétés requises incluses
- Propriétés recommandées ajoutées
- Adapté au type de page
- URLs complètes (pas relatives)
- Dates au format ISO 8601
- Testable dans Google Rich Results Test
- Conforme aux guidelines Google
